        );

        // Check member.
        let member = contract
            .sender(alice)
            .get_role_member(ROLE.into(), U256::ZERO)
            .motsu_expect("should return alice");
        assert_eq!(member, alice);

        assert_eq!(
            contract.sender(alice).get_role_members(ROLE.into()),
