impl<P: FpParams<N>, const N: usize> Fp<P, N> {
    /// A multiplicative generator of the field.
    /// [`Self::GENERATOR`] is an element having multiplicative order
    /// `MODULUS - 1`.
    ///
    /// Every element of the field should be represented as `GENERATOR^i`
    pub const GENERATOR: Fp<P, N> = P::GENERATOR;
    /// Multiplicative identity of the field, i.e., the element `e`
    /// such that, for all elements `f` of the field, `e * f = f`.
    pub const ONE: Fp<P, N> = Fp::new_unchecked(P::R);
    /// Additive identity of the field, i.e., the element `e`
    /// such that, for all elements `f` of the field, `e + f = f`.
    pub const ZERO: Fp<P, N> = Fp::new_unchecked(Uint { limbs: [0; N] });

    /// Construct a new field element from [`Uint`].
    ///
    /// Unlike [`Self::new`], this method does not perform Montgomery reduction.
    /// This method should be used only when constructing an element from an
    /// integer that has already been put in Montgomery form.
    #[must_use]
    #[inline(always)]
    pub const fn new_unchecked(element: Uint<N>) -> Self {
        Self { montgomery_form: element, phantom: PhantomData }
    }

    #[doc(hidden)]
    #[inline(always)]
    #[must_use]
    pub const fn is_ge_modulus(&self) -> bool {
        self.montgomery_form.ge(&P::MODULUS)
    }

    #[inline(always)]
    const fn subtract_modulus(mut self) -> Self {
        if self.is_ge_modulus() {
            self.montgomery_form =
                self.montgomery_form.wrapping_sub(&P::MODULUS);
        }
        self
    }

    /// Construct a new field element from its underlying
    /// [`struct@Uint`] data type.
    #[inline]
    #[must_use]
    pub const fn new(element: Uint<N>) -> Self {
        let r = Self { montgomery_form: element, phantom: PhantomData };
        if r.is_zero() {
            r
        } else {
            Fp::<P, N>::mul(
                &r,
                &Fp { montgomery_form: P::R2, phantom: PhantomData },
            )
        }
    }

    /// Multiply `self` to `rhs` and return the result (constant).
    ///
    /// Implements the Montgomery multiplication algorithm [reference].
    ///
    /// [reference]: https://en.wikipedia.org/wiki/Montgomery_modular_multiplication
    #[inline(always)]
    #[must_use]
    pub const fn mul(&self, rhs: &Self) -> Self {
        let (carry, result) = self.mul_without_cond_subtract(rhs);
        if P::HAS_MODULUS_SPARE_BIT {
            result.subtract_modulus()
        } else {
            result.carrying_sub_modulus(carry)
        }
    }

    /// Negate `self` and return the result (constant).
    #[inline(always)]
    #[must_use]
    pub const fn neg(self) -> Self {
        if self.is_zero() {
            return self;
        }

        // Should not overflow. Montgomery should always be less than modulus.
        let (res, _) = Self::MODULUS.checked_sub(&self.montgomery_form);
        Fp::new_unchecked(res)
    }

    /// Returns true if this number is zero (constant).
    #[must_use]
    pub const fn is_zero(&self) -> bool {
        self.montgomery_form.is_zero()
    }

    /// Subtract modulus from `self` with carry and return the result.
    #[inline(always)]
    const fn carrying_sub_modulus(mut self, carry: bool) -> Self {
        if carry || self.is_ge_modulus() {
            self.montgomery_form =
                self.montgomery_form.wrapping_sub(&P::MODULUS);
        }
