    fn eq(&self, other: &Self) -> bool {
        if self.is_zero() {
            return other.is_zero();
        }

        if other.is_zero() {
            return false;
        }

        // Checking equality without multiplication,
        // e.g. x1/z1 == x2/z2 <==> x1 * z2 == x2 * z1.
        (self.x * other.z) == (other.x * self.z)
            && (self.y * other.z) == (other.y * self.z)
    }
}

