        let verifying_key = VerifyingKey::from_affine(AffinePoint::zero());
        let signature = Signature::from_affine_R_s(
            AffinePoint::zero(),
            Scalar::from_bigint(U256::ZERO),
        );

        assert!(!verifying_key.is_valid(b"any message", &signature));
    }

