}

/// Ed25519 key for signature verification (public key).
#[derive(Copy, Clone, Default, PartialEq)]
pub struct VerifyingKey {
    /// Edwards point used for curve arithmetic operations.
    pub point: ProjectivePoint,
}

impl VerifyingKey {
    /// Construct verifying key from affine point.
    #[must_use]
    pub fn from_affine(point: AffinePoint) -> Self {
        VerifyingKey { point: point.into() }
    }

    /// Verify a signature on a message with this keypair's public key.
    #[must_use]
    pub fn is_valid(&self, message: &[u8], signature: &Signature) -> bool {
        if self.point.z.is_zero() || signature.R.z.is_zero() {
            return false;
        }

        let public_key = self.point.into_affine();
        let R = signature.R.into_affine();

        if public_key.is_zero()
            || R.is_zero()
            || !public_key.is_on_curve()
            || !R.is_on_curve()
            || !public_key.is_in_prime_order_subgroup()
            || !R.is_in_prime_order_subgroup()
        {
            return false;
        }

        // Rebuild projective points from their validated affine coordinates.
        // This discards any inconsistent T coordinate supplied by callers.
        let verifying_key = Self::from_affine(public_key);
        let signature = Signature::from_affine_R_s(R, signature.s);

        let expected_r = verifying_key.compute_R(&signature, message);
        expected_r == signature.R
    }

    /// Helper for verification. Computes the expected `R` component of the
    /// signature. The caller compares this to the real `R` component.
    /// This computes `H(R || A || M)` where `H` is the 512-bit hash function
    /// given by `CtxDigest` (this is SHA-512 in spec-compliant Ed25519).
    fn compute_R(
        &self,
        signature: &Signature,
        message: &[u8],
    ) -> ProjectivePoint {
        let R = signature.R;
        let A = self.point;

        let mut h = Sha512::new();
        h.update(CompressedPointY::from(R.into_affine()));
        h.update(CompressedPointY::from(A.into_affine()));
        h.update(message);
}

