        scalar_bytes[0] &= 0b1111_1000;
        scalar_bytes[31] &= 0b0111_1111;
        scalar_bytes[31] |= 0b0100_0000;
        let scalar = Scalar::from_bigint(U256::from_bytes_le(&scalar_bytes));
        scalar_bytes.zeroize();
        Self { scalar, hash_prefix }
    }
