                #[cfg(feature = "contract-client-gen")]
                #[allow(clippy::needless_update)]
                #[allow(non_snake_case)]
                impl<#generic_params> #struct_path #where_clause {
                    pub fn new(address: stylus_sdk::alloy_primitives::Address) -> Self {
                        Self {
