    /// # Arguments
    ///
    /// * `from` - Owner's address.
    /// * `to` - Recipient's address.
    /// * `value` - Amount to be transferred.
    ///
    /// # Errors
    ///
    /// * [`Error::InsufficientBalance`] - If the `from` address doesn't have
    ///   enough tokens.
    ///
    /// # Events
    ///
    /// * [`Transfer`].
    ///
    /// # Panics
    ///
    /// * If `total_supply` exceeds [`U256::MAX`]. It may happen during `mint`
    ///   operation.
    pub fn _update(
        &mut self,
        from: Address,
        to: Address,
        value: U256,
    ) -> Result<(), Error> {
        if from.is_zero() {
            // Mint operation. Overflow check required: the rest of the code
            // assumes that `total_supply` never overflows.
            self.total_supply.add_assign_checked(
                value,
                "should not exceed `U256::MAX` for `total_supply`",
            );
        } else {
            let from_balance = self.balances.get(from);
            if from_balance < value {
                return Err(Error::InsufficientBalance(
                    ERC20InsufficientBalance {
                        sender: from,
                        balance: from_balance,
                        needed: value,
                    },
                ));
            }
            // Overflow not possible:
            // `value` <= `from_balance` <= `total_supply`.
            self.balances.setter(from).set(from_balance - value);
        }

        if to.is_zero() {
            // Overflow not possible:
            // `value` <= `total_supply` or
            // `value` <= `from_balance` <= `total_supply`.
            self.total_supply.sub_assign_unchecked(value);
        } else {
            // Overflow not possible:
            // `balance_to` + `value` is at most `total_supply`,
            // which fits into a `U256`.
            self.balances.setter(to).add_assign_unchecked(value);
        }

        self.vm().log(Transfer { from, to, value });

        Ok(())
    }

    /// Destroys a `value` amount of tokens from `account`,
    /// lowering the total supply.
    ///
    /// # Arguments
    ///
    /// * `account` - Owner's address.
    pub fn constructor(&mut self, cap: U256) -> Result<(), Error> {
        if cap.is_zero() {
            return Err(Error::InvalidCap(ERC20InvalidCap { cap }));
        }
        self.cap.set(cap);
        Ok(())
    }
}

impl Capped {
    /// Checks whether increasing the current supply by `increase` stays
    /// within the configured cap.
    ///
    /// Call this before minting in the consuming contract. Including
    /// [`Capped`] does not automatically route an
    /// [`Erc20`](crate::token::erc20::Erc20) mint through this
    /// check.
    ///
    /// # Errors
    ///
    /// * [`Error::ExceededCap`] - If the resulting supply is greater than the
    ///   configured cap.
    pub fn _check_cap(
        &self,
        current_supply: U256,
        increase: U256,
    ) -> Result<(), Error> {
        let increased_supply = current_supply
            .checked_add(increase)
            .expect("increased supply should not overflow U256");
        let cap = self.cap.get();

        if increased_supply > cap {
            return Err(Error::ExceededCap(ERC20ExceededCap {
                increased_supply,
                cap,
            }));
        }

        Ok(())
    }
}

#[public]
impl ICapped for Capped {
    fn cap(&self) -> U256 {
        self.cap.get()
    }
}

