/// cannot share state across invocations), and collisions with methods inherited via
/// `#[implements]` (only trait type paths are available — the inherited trait's function
/// signatures are not accessible during proc-macro expansion).
/// See the `#[public]` macro documentation in `lib.rs` for user-facing details.
pub(super) fn selector_collision_checks<E: FnExtension>(funcs: &[PublicFn<E>]) -> Vec<syn::Item> {
    let functions = regular_functions(funcs);

    // Collect per-function data used in the pairwise comparison below.
    let func_data: Vec<_> = functions
        .iter()
        .map(|f| {
            (
                f.selector_const(),
                f.selector_name(),
                f.display_label(),
                f.name.span(),
            )
        })
        .collect();
    let n = func_data.len();
    let mut checks: Vec<syn::Item> = Vec::with_capacity(n * n.saturating_sub(1) / 2);
    for (i, (const_a, sel_a, label_a, _)) in func_data.iter().enumerate() {
        for (const_b, sel_b, label_b, span) in &func_data[i + 1..] {
            let msg = format!(
                "Stylus SDK: ABI selector collision: {label_a} and {label_b} produce the same \
                 4-byte selector. Use #[selector(name = \"...\")] to assign a distinct name, \
                 or rename one",
            );
            // The cfg gate is intentional: `contract-client-gen` generates call stubs for
            // external contracts whose ABI the user does not control. Blocking compilation
            // over a selector collision in a foreign interface would be unhelpful — the
            // collision only matters for routing, which is not emitted in contract-client-gen mode.
            checks.push(parse_quote_spanned! { *span =>
                #[cfg(not(feature = "contract-client-gen"))]
                const _: () = {
                    use stylus_sdk::function_selector;
                    #const_a
                    #const_b
                    assert!(#sel_a != #sel_b, #msg);
                };
            });
        }
    }
    checks
}

/// Returns only `FnKind::Function` entries, excluding fallback, receive, and constructor.
fn regular_functions<E: FnExtension>(funcs: &[PublicFn<E>]) -> Vec<&PublicFn<E>> {
    funcs
        .iter()
        .filter(|f| matches!(f.kind, FnKind::Function))
    item: syn::ItemFn,
}

impl ToTokens for EntrypointFn {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        self.item.to_tokens(tokens);
    }
}

struct EntrypointStruct {
    item: syn::ItemStruct,
    item_contract_client_gen: syn::ItemStruct,
    top_level_storage_impl: syn::ItemImpl,
    struct_entrypoint_fn: syn::ItemFn,
}

impl ToTokens for EntrypointStruct {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        tokens.extend(quote! {
            #[cfg(not(feature = "contract-client-gen"))]
        });
        self.item.to_tokens(tokens);
        tokens.extend(quote! {
            #[cfg(feature = "contract-client-gen")]
        });
        self.item_contract_client_gen.to_tokens(tokens);

        self.top_level_storage_impl.to_tokens(tokens);
        self.struct_entrypoint_fn.to_tokens(tokens);
    }
}

fn top_level_storage_impl(item: &syn::ItemStruct) -> syn::ItemImpl {
    let name = &item.ident;
    let (impl_generics, ty_generics, where_clause) = item.generics.split_for_impl();
    parse_quote! {
        #[cfg(not(feature = "contract-client-gen"))]
            where_clause,
            funcs,
            associated_types,
        }
    }
}

impl ToTokens for PublicTrait {
    fn to_tokens(&self, tokens: &mut proc_macro2::TokenStream) {
        tokens.extend(self.contract_client_gen());
        // Emit collision checks for trait definitions too, so that library crates
        // defining a #[public] trait without a corresponding impl still get checked.
        // When both the trait and its impl exist in the same crate, the compiler will
        // evaluate redundant (but harmless) duplicate const assertions; on a collision,
        // the user may see the error reported twice. Deduplication is not feasible because
        // the trait and impl are processed by separate proc-macro invocations that cannot
        // communicate.
        //
        // Skip checks for generic traits: the generic type parameters would not be in
        // scope in the emitted `const _: ()` items. The concrete `impl Trait<...> for S`
        // block will still emit its own collision checks with the resolved types.
        if self.generic_params.is_empty() {
            for check in types::selector_collision_checks(&self.funcs) {
                check.to_tokens(tokens);
            }
        }
    }
}

impl ToTokens for PublicImpl {
    fn to_tokens(&self, tokens: &mut proc_macro2::TokenStream) {
        tokens.extend(self.struct_for_export_abi());
        tokens.extend(self.contract_client_gen());
        tokens.extend(self.print_from_args_fn());
        // Skip collision checks for generic impl blocks: the emitted `const` items
        // would reference type parameters that are not in scope at module level.
        if self.generic_params.is_empty() {
            for check in types::selector_collision_checks(&self.funcs) {
                check.to_tokens(tokens);
            }
        }
        self.impl_router().to_tokens(tokens);
        Extension::codegen(self).to_tokens(tokens);
    }
}

impl From<&mut syn::ItemImpl> for PublicImpl {
    fn from(node: &mut syn::ItemImpl) -> Self {
        // parse traits from #[implements(...)] attribute
        let mut implements = Vec::new();
        if let Some(attr) = consume_attr::<attrs::Implements>(&mut node.attrs, "implements") {
            implements.extend(attr.types);
        }

