L87:     /// Add a function to the interface definition.
L88:     fn add_function(
L89:         &mut self,
L90:         attrs: &[syn::Attribute],
L91:         name: &syn_solidity::SolIdent,
L92:         purity: Purity,
L93:         params: FunctionParameters,
L94:         return_type: syn::Type,
L95:     ) {
L96:         let rust_name = syn::Ident::new(&name.to_string().to_case(Case::Snake), name.span());
L97:         // build selector
L98:         let selector = build_selector(name, params.params.iter().map(|p| &p.type_info.sol_type));
L99:         let [selector0, selector1, selector2, selector3] = selector;
L100: 
L101:         let (context, call) = purity.get_context_and_call();
L102:         let sol_args = params
L103:             .params
L104:             .iter()
L105:             .map(|param| param.type_info.alloy_type.clone());
L106:         let rust_args = params.params.iter().map(|param| -> syn::FnArg {
L107:             let FunctionParameter {
L108:                 name,
L109:                 type_info: SolidityTypeInfo { alloy_type, .. },
L110:                 ..
L111:             } = param;
L112:             parse_quote!(#name: <#alloy_type as #SolType>::RustType)
L113:         });
L114:         let rust_arg_names = params.params.iter().map(|param| param.name.clone());
L115:         // For multi-value returns, return_type is already a tuple (e.g. (Uint<256>, String)),
L116:         // so we decode it directly. For single returns, we wrap in a 1-tuple and unwrap with .0.
L117:         let decode_expr: syn::Expr = match &return_type {
L118:             syn::Type::Tuple(t) if t.elems.len() != 1 => {
L119:                 parse_quote!(<#return_type as #SolType>::abi_decode_params_validate(&returned)?)
L120:             }
L121:             _ => {
L122:                 parse_quote!(<(#return_type,) as #SolType>::abi_decode_params_validate(&returned)?.0)
L123:             }
L124:         };
L125:         self.item_impl.items.push(parse_quote! {
L126:             #(#attrs)*
L127:             pub fn #rust_name(
L128:                 &self,
L129:                 host: &impl stylus_sdk::stylus_core::host::Host,
L130:                 context: impl #context #(, #rust_args)*
L131:             ) -> Result<<#return_type as #SolType>::RustType, stylus_sdk::stylus_core::calls::errors::Error>
L132:             {
L133:                 let args = <(#(#sol_args,)*) as #SolType>::abi_encode_params(&(#(#rust_arg_names,)*));
L134:                 let mut calldata = vec![#selector0, #selector1, #selector2, #selector3];
L135:                 calldata.extend(args);
L136:                 let returned = #call(host, context, self.address, &calldata)?;
L137:                 Ok(#decode_expr)
L138:             }
L139:         });
L140:     }
