from pathlib import Path
import re
roots = [Path('/tmp/rust-contracts-stylus-v030/contracts/src'), Path('/tmp/rust-contracts-stylus-v030/examples')]
new_roots = [Path('contracts/src'), Path('examples')]

def extract(root):
    out = {}
    for p in root.rglob('*.rs'):
        lines = p.read_text().splitlines()
        for i, line in enumerate(lines):
            if not re.match(r'\s*#\[storage\]\s*$', line):
                continue
            j = i + 1
            while j < len(lines) and not re.search(r'\b(?:struct|enum)\s+\w+', lines[j]):
                j += 1
            if j == len(lines):
                continue
            m = re.search(r'\b(?:struct|enum)\s+(\w+)', lines[j])
            name = m.group(1)
            depth = 0
            started = False
            fields = []
            for k in range(j, len(lines)):
                s = lines[k]
                for c in s:
                    if c == '{':
                        depth += 1
                        started = True
                    elif c == '}':
                        depth -= 1
                if started and depth == 1:
                    f = re.match(r'\s*(?:(?:pub)(?:\([^)]*\))?\s+)?(\w+)\s*:', s)
                    if f:
                        fields.append((f.group(1), s.strip()))
                if started and depth == 0:
                    break
            out[(str(p.relative_to(root)), name)] = fields
    return out

old = {}
for root in roots:
    for key, val in extract(root).items(): old[(root.name,)+key] = val
new = {}
for root in new_roots:
    for key, val in extract(root).items(): new[(root.name,)+key] = val
for key in sorted(set(old)|set(new)):
    if old.get(key) != new.get(key):
        print('\n', key)
        print(' old:', old.get(key))
        print(' new:', new.get(key))
