L98:     R: Router<S>,
L99:     S: StorageType + TopLevelStorage + BorrowMut<R::Storage> + ValueDenier,
L100: {
L101:     let mut storage = unsafe { S::new(U256::ZERO, 0, host) };
L102:     if input.is_empty() {
L103:         console!("no calldata provided");
L104:         if let Some(res) = R::receive(&mut storage) {
L105:             return res.map(|_| Vec::new());
L106:         }
L107:         // Try fallback function with no inputs if defined.
L108:         if let Some(res) = R::fallback(&mut storage, &[]) {
L109:             return res;
L110:         }
L111:         // Revert as no receive or fallback were defined.
L112:         return Err(Vec::new());
L113:     }
L114:     if input.len() >= 4 {
L115:         let selector = u32::from_be_bytes(TryInto::try_into(&input[..4]).unwrap());
L116:         if selector == CONSTRUCTOR_SELECTOR {
L117:             if let Some(res) = R::constructor(&mut storage, &input[4..]) {
L118:                 return res;
L119:             }
L120:         } else if let Some(res) = R::route(&mut storage, selector, &input[4..]) {
L121:             return res;
L122:         } else {
L123:             console!("unknown method selector: {selector:08x}");
L124:         }
L125:     }
L126:     // Try fallback function.
L127:     if let Some(res) = R::fallback(&mut storage, &input) {
L128:         return res;
L129:     }
L130: 
L131:     Err(Vec::new())
L132: }
